) AS [Source] ([CollectionDate],[DebitRunId],[ProfileId],[ExtractScheduleId])
ON ([Target].[CollectionDate] = [Source].[CollectionDate] AND [Target].[DebitRunId] = [Source].[DebitRunId] AND [Target].[ProfileId] = [Source].[ProfileId])
WHEN MATCHED AND (
	NULLIF([Source].[ExtractScheduleId], [Target].[ExtractScheduleId]) IS NOT NULL OR NULLIF([Target].[ExtractScheduleId], [Source].[ExtractScheduleId]) IS NOT NULL) THEN
 UPDATE SET
  [Target].[ExtractScheduleId] = [Source].[ExtractScheduleId]
WHEN NOT MATCHED BY TARGET THEN
 INSERT([CollectionDate],[DebitRunId],[ProfileId],[ExtractScheduleId])
 VALUES([Source].[CollectionDate],[Source].[DebitRunId],[Source].[ProfileId],[Source].[ExtractScheduleId])
WHEN NOT MATCHED BY SOURCE THEN 
 DELETE;

DECLARE @mergeError int
 , @mergeCount int
SELECT @mergeError = @@ERROR, @mergeCount = @@ROWCOUNT
IF @mergeError != 0
 BEGIN
 PRINT 'ERROR OCCURRED IN MERGE FOR [ProfileDates]. Rows affected: ' + CAST(@mergeCount AS VARCHAR(100)); -- SQL should always return zero rows affected
 END
ELSE
 BEGIN
 PRINT '[ProfileDates] rows affected by MERGE: ' + CAST(@mergeCount AS VARCHAR(100));
 END
